import numpy as np
from scipy import stats


def _fit(X, y, it=30):
    X = np.column_stack([np.ones(len(y)), X]) if X.size else np.ones((len(y), 1))
    b = np.zeros(X.shape[1])
    for _ in range(it):
        eta = np.clip(X @ b, -30, 30)
        p = 1 / (1 + np.exp(-eta))
        w = p * (1 - p) + 1e-9
        H = X.T @ (X * w[:, None]) + 1e-6 * np.eye(X.shape[1])
        step = np.linalg.solve(H, X.T @ (y - p))
        b += step
        if np.max(np.abs(step)) < 1e-8:
            break
    p = np.clip(1 / (1 + np.exp(-np.clip(X @ b, -30, 30))), 1e-12, 1 - 1e-12)
    return float(np.sum(y * np.log(p) + (1 - y) * np.log(1 - p)))


def design(feats):
    X, y = np.asarray(feats.x, float), np.asarray(feats.y, float)
    ids, p = list(feats.ids), X.shape[1]
    R = np.corrcoef(X, rowvar=False)
    sel, base = [], _fit(np.empty((len(y), 0)), y)
    while len(sel) < MAX_DRIVERS:
        alpha = (0.05 if not sel else 0.01) / p
        best, bj = -np.inf, None
        for j in range(p):
            if j in sel or any(abs(R[j, k]) >= 0.6 for k in sel):
                continue
            ll = _fit(X[:, sel + [j]], y)
            if ll > best:
                best, bj = ll, j
        if bj is None or stats.chi2.sf(2 * (best - base), 1) > alpha:
            break
        sel.append(bj)
        base = best
    changed = True
    while changed and sel:
        changed = False
        full = _fit(X[:, sel], y)
        for k in list(sel):
            rest = [s for s in sel if s != k]
            if stats.chi2.sf(2 * (full - _fit(X[:, rest], y)), 1) > 0.01 / p:
                sel.remove(k)
                changed = True
                break
    prods, npair = [], p * (p + 1) / 2
    for a in range(p):
        for b in range(a, p):
            if a != b and abs(R[a, b]) >= 0.6:
                continue
            mains = sorted(set(sel) | {a, b})
            l0 = _fit(X[:, mains], y)
            l1 = _fit(np.column_stack([X[:, mains], X[:, a] * X[:, b]]), y)
            pv = stats.chi2.sf(2 * (l1 - l0), 1)
            if pv < 0.01 / npair:
                prods.append((pv, a, b))
    prods = sorted(prods)[:2]
    drivers = [ids[j] for j in sel]
    for _, a, b in prods:
        for j in (a, b):
            if ids[j] not in drivers:
                drivers.append(ids[j])
    cols = sorted(set(sel) | {j for _, a, b in prods for j in (a, b)})
    return Design(drivers=tuple(drivers[:MAX_DRIVERS]), columns=tuple(ids[j] for j in cols),
                  products=tuple((ids[a], ids[b]) for _, a, b in prods), loadings={})

